function adminShell(body,tab){
  const allowed=roleNav[state.user.role]||[];
  return `<div class="admin"><aside><a data-nav href="/admin" class="admin-brand"><img src="/assets/xanh-sky-first-logo.png" alt="Xanh"><span>XANH<br><small>Management Center</small></span></a><nav>${allowed.map(k=>`<a data-nav class="${tab===k?'active':''}" href="/admin/${k}">${labels[k]}</a>`).join('')}</nav></aside><section class="admin-main"><header><button class="command" id="command-open">⌕ Tìm kiếm & lệnh nhanh <kbd>Ctrl K</kbd></button><a data-nav href="/">Xem website ↗</a><b>${esc(state.user.name)}</b><span class="role-pill">${esc(roleLabel(state.user.role))}</span><button id="logout">Đăng xuất</button></header><div class="admin-body">${body}</div></section></div>`;
}
function adminHead(t,d,actions=''){return `<div class="admin-head"><div><span class="eyebrow">XANH MANAGEMENT</span><h1>${esc(t)}</h1><p>${esc(d)}</p></div><div class="admin-actions">${actions}</div></div>`}
function table(rows,heads){return `<div class="table"><div class="tr th" style="--cols:${heads.length}">${heads.map(h=>`<div>${h}</div>`).join('')}</div>${rows.map(r=>`<div class="tr" style="--cols:${heads.length}">${r.map(c=>`<div>${c??''}</div>`).join('')}</div>`).join('')||'<div class="empty">Chưa có dữ liệu.</div>'}</div>`}
function statusBadge(v){return `<span class="status status-${esc(v)}">${esc(v)}</span>`}
function closeModal(){state.modal?.remove();state.modal=null}
function makeModal(html,wide=false){closeModal();const wrap=document.createElement('div');wrap.className='modal';wrap.innerHTML=`<div class="modal-card ${wide?'wide':''}">${html}</div>`;document.body.append(wrap);wrap.addEventListener('click',e=>{if(e.target===wrap)closeModal()});state.modal=wrap;return wrap}

async function uploadMedia(file,meta={}){
  const fd=new FormData();fd.append('file',file);if(meta.alt_text)fd.append('alt_text',meta.alt_text);if(meta.caption)fd.append('caption',meta.caption);if(meta.credit)fd.append('credit',meta.credit);
  if(file.type.startsWith('image/')){try{const size=await new Promise((resolve,reject)=>{const img=new Image(),u=URL.createObjectURL(file);img.onload=()=>{resolve([img.naturalWidth,img.naturalHeight]);URL.revokeObjectURL(u)};img.onerror=reject;img.src=u});fd.append('width',size[0]);fd.append('height',size[1])}catch{}}
  return (await api('/api/admin/media',{method:'POST',body:fd})).item;
}
async function openMediaPicker({onSelect,imagesOnly=true,currentId=null}={}){
  let items=(await api('/api/admin/media')).items;if(imagesOnly)items=items.filter(x=>String(x.mime_type).startsWith('image/'));
  const m=makeModal(`<div class="modal-head"><div><span class="eyebrow">MEDIA LIBRARY</span><h2>Chọn ảnh / tệp</h2></div><button class="icon-btn modal-close">×</button></div><div class="picker-tools"><input id="picker-search" placeholder="Tìm theo tên hoặc alt..."><label class="btn primary">＋ Tải lên<input id="picker-upload" type="file" ${imagesOnly?'accept="image/*"':''} hidden></label></div><div class="media-grid picker-grid">${items.map(x=>`<button type="button" class="media-choice ${Number(currentId)===Number(x.id)?'selected':''}" data-id="${x.id}"><span>${String(x.mime_type).startsWith('image/')?`<img src="${x.url}" alt="${esc(x.alt_text||x.filename)}" loading="lazy">`:'📄'}</span><b>${esc(x.filename)}</b><small>${esc(x.alt_text||'Chưa có alt')}</small></button>`).join('')||'<div class="empty">Chưa có media phù hợp.</div>'}</div>`,true);
  $('.modal-close',m).onclick=closeModal;
  $$('.media-choice',m).forEach(btn=>btn.onclick=()=>{const item=items.find(x=>String(x.id)===btn.dataset.id);onSelect?.(item);closeModal()});
  $('#picker-search',m).oninput=e=>{const q=e.target.value.toLowerCase();$$('.media-choice',m).forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(q))};
  $('#picker-upload',m).onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const item=await uploadMedia(file,{alt_text:file.name.replace(/\.[^.]+$/,'')});toast('Đã tải lên R2');onSelect?.(item);closeModal()}catch(x){toast(x.message,'error')}};
}

function personPhotoPickerHtml(item){return `<div class="photo-picker">${item?.url?`<img src="${item.url}" alt="${esc(item.alt_text||item.filename||'Ảnh chân dung')}">`:'<div class="person-ph">Ảnh</div>'}<input type="hidden" name="photo_media_id" value="${item?.id||''}"><div><button type="button" class="btn glass choose-photo">Chọn từ Media Library</button><label class="btn glass">Tải ảnh từ máy<input class="upload-photo" type="file" accept="image/*" hidden></label><button type="button" class="btn danger remove-photo">Gỡ ảnh khỏi hồ sơ</button><small>Ảnh vuông, dọc, ngang hoặc độ phân giải lớn đều được chấp nhận. Frontend tự crop bằng object-fit và focus point của media.</small></div></div>`}
async function peopleAdmin(){
  const x=(await api('/api/admin/people')).items;
  return adminHead('Con người Xanh','Hồ sơ công khai, ảnh R2, URL riêng, SEO và quyền index.',`<button class="btn primary" data-action="new-person">＋ Thêm người</button>`)+table(x.map(p=>[p.photo_url?`<img class="avatar-sm" src="${p.photo_url}" alt="">`:'—',`<b>${esc(p.name)}</b><br><small>${esc(p.slug)}</small>`,esc(p.title||'—'),p.is_public?'Công khai':'Ẩn',p.allow_index?'Index':'Noindex',`<button class="link-btn edit-person" data-id="${p.id}">Sửa</button> · <a data-nav href="/con-nguoi/${esc(p.slug)}">Xem ↗</a>`]),['Ảnh','Họ tên','Chức danh','Hiển thị','SEO','Thao tác']);
}
async function personEditor(person=null){
  let photo=null;if(person?.photo_media_id)photo={id:person.photo_media_id,url:person.photo_url,alt_text:person.photo_alt};
  const m=makeModal(`<div class="modal-head"><div><span class="eyebrow">CON NGƯỜI XANH</span><h2>${person?'Chỉnh sửa hồ sơ':'Thêm người'}</h2></div><button class="icon-btn modal-close">×</button></div><form id="person-editor">${personPhotoPickerHtml(photo)}<div class="form-grid two"><label>Họ và tên<input name="name" value="${esc(person?.name||'')}" required></label><label>Slug<input name="slug" value="${esc(person?.slug||'')}"></label><label>Chức danh<input name="title" value="${esc(person?.title||'')}"></label><label>Nhóm vai trò<input name="role_group" value="${esc(person?.role_group||'coordination')}"></label><label class="full">Giới thiệu<textarea name="bio">${esc(person?.bio||'')}</textarea></label><label class="full">Lĩnh vực / chuyên môn<input name="expertise" value="${esc(person?.expertise||'')}"></label><label>Thứ tự<input name="sort_order" type="number" value="${Number(person?.sort_order||0)}"></label><label>Website / liên kết chính<input name="link_website" value="${esc(person?.links?.website||'')}"></label><label class="full">SEO title<input name="seo_title" value="${esc(person?.seo?.title||'')}"></label><label class="full">SEO description<textarea name="seo_description">${esc(person?.seo?.description||'')}</textarea></label><label class="choice"><input type="checkbox" name="is_public" ${person?.is_public?'checked':''}> Công khai hồ sơ</label><label class="choice"><input type="checkbox" name="allow_index" ${person?.allow_index?'checked':''}> Cho phép Google/Bing index</label></div><div class="sticky-actions"><button type="button" class="btn glass modal-close2">Hủy</button><button class="btn primary">${person?'Lưu thay đổi':'Tạo hồ sơ'}</button></div></form>`,true);
  $('.modal-close',m).onclick=$('.modal-close2',m).onclick=closeModal;
  const form=$('#person-editor',m);
  const hidden=()=>$('input[name="photo_media_id"]',form);
  $('.choose-photo',m).onclick=()=>openMediaPicker({currentId:hidden().value,onSelect:item=>{hidden().value=item.id;$('.photo-picker>img,.photo-picker>.person-ph',form).outerHTML=`<img src="${item.url}" alt="${esc(item.alt_text||item.filename)}">`}});
  $('.upload-photo',m).onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{const item=await uploadMedia(f,{alt_text:form.name.value||f.name});hidden().value=item.id;$('.photo-picker>img,.photo-picker>.person-ph',form).outerHTML=`<img src="${item.url}" alt="${esc(item.alt_text||item.filename)}">`;toast('Ảnh đã tải lên R2')}catch(x){toast(x.message,'error')}};
  $('.remove-photo',m).onclick=()=>{hidden().value='';$('.photo-picker>img,.photo-picker>.person-ph',form).outerHTML='<div class="person-ph">Ảnh</div>'};
  form.oninput=()=>state.dirty=true;
  form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),body={name:f.get('name'),slug:f.get('slug'),title:f.get('title'),role_group:f.get('role_group'),bio:f.get('bio'),expertise:f.get('expertise'),sort_order:Number(f.get('sort_order')||0),photo_media_id:f.get('photo_media_id')?Number(f.get('photo_media_id')):null,is_public:f.has('is_public'),allow_index:f.has('allow_index'),links:{website:f.get('link_website')},seo:{title:f.get('seo_title'),description:f.get('seo_description')}};try{if(person)await api(`/api/admin/person/${person.id}`,{method:'PUT',body});else await api('/api/admin/people',{method:'POST',body});state.dirty=false;closeModal();toast('Đã lưu hồ sơ Con người Xanh');admin('people')}catch(x){toast(x.message,'error')}};
}

function fieldEditorRow(f,i){
  const types=[['text','Văn bản ngắn'],['email','Email'],['phone','Số điện thoại'],['url','Liên kết / URL'],['textarea','Đoạn văn'],['select','Danh sách chọn'],['radio','Chọn một'],['checkbox','Chọn nhiều'],['date','Ngày'],['time','Giờ'],['datetime','Ngày & giờ'],['number','Số'],['rating','Thang điểm'],['file','Tải tệp / ảnh'],['signature','Chữ ký tay'],['consent','Xác nhận / đồng ý'],['section','Tiêu đề phần']];
  return `<div class="builder-row" data-i="${i}"><span class="drag">⋮⋮</span><select class="field-type">${types.map(([v,l])=>`<option value="${v}" ${f.type===v?'selected':''}>${l}</option>`).join('')}</select><input class="field-label" value="${esc(f.label||'')}" placeholder="Nhãn trường"><label class="mini-check"><input class="field-required" type="checkbox" ${f.required?'checked':''}> Bắt buộc</label><button type="button" class="icon-btn field-up">↑</button><button type="button" class="icon-btn field-down">↓</button><button type="button" class="icon-btn field-dup">⧉</button><button type="button" class="icon-btn field-del">×</button><input class="field-options" value="${esc((f.options||[]).join(' | '))}" placeholder="Lựa chọn: A | B | C" ${['select','radio','checkbox'].includes(f.type)?'':'hidden'}></div>`;
}
async function formsAdmin(){
  const x=(await api('/api/admin/forms')).items;
  return adminHead('Form Builder','Tạo và quản lý biểu mẫu trực tiếp: trường dữ liệu, deadline, capacity, email xác nhận và cover R2.',`<button class="btn primary" data-action="new-form">＋ Tạo form</button>`)+table(x.map(f=>[`<b>${esc(f.name)}</b><br><small>/${esc(f.slug)}</small>`,esc(f.kind),statusBadge(f.status),(f.fields||[]).length,f.capacity||'—',`<button class="link-btn edit-form" data-id="${f.id}">Sửa</button> · <button class="link-btn delete-form" data-id="${f.id}" data-name="${esc(f.name)}">Xóa</button> · <a data-nav href="/tham-gia/${esc(f.slug)}">Xem ↗</a>`]),['Biểu mẫu','Loại','Trạng thái','Trường','Capacity','Thao tác']);
}
async function formEditor(form=null){
  const data=form||{fields:[],settings:{},status:'draft',kind:'volunteer'};let fields=structuredClone(data.fields||[]),cover=data.cover_media_id?{id:data.cover_media_id,url:data.cover_url}:null;
  const m=makeModal(`<div class="modal-head"><div><span class="eyebrow">FORM BUILDER</span><h2>${form?'Chỉnh sửa biểu mẫu':'Tạo biểu mẫu'}</h2></div><button class="icon-btn modal-close">×</button></div><form id="form-editor"><div class="form-grid two"><label>Tên biểu mẫu<input name="name" value="${esc(data.name||'')}" required></label><label>Slug<input name="slug" value="${esc(data.slug||'')}"></label><label>Loại<input name="kind" value="${esc(data.kind||'volunteer')}"></label><label>Trạng thái<select name="status"><option value="draft" ${data.status==='draft'?'selected':''}>draft</option><option value="open" ${data.status==='open'?'selected':''}>open</option><option value="closed" ${data.status==='closed'?'selected':''}>closed</option><option value="archived" ${data.status==='archived'?'selected':''}>archived</option></select></label><label class="full">Mô tả<textarea name="description">${esc(data.description||'')}</textarea></label><label>Mở lúc<input type="datetime-local" name="opens_at" value="${localDateTime(data.opens_at)}"></label><label>Đóng lúc<input type="datetime-local" name="closes_at" value="${localDateTime(data.closes_at)}"></label><label>Capacity<input type="number" min="1" name="capacity" value="${data.capacity||''}"></label></div><div class="cover-editor"><h3>Ảnh bìa</h3><div id="form-cover-preview">${cover?`<img src="${cover.url}" alt="">`:'<div class="empty small">Chưa chọn ảnh</div>'}</div><input type="hidden" name="cover_media_id" value="${cover?.id||''}"><button type="button" class="btn glass" id="choose-form-cover">Chọn / tải ảnh</button><button type="button" class="btn danger" id="remove-form-cover">Gỡ ảnh</button></div><div class="builder-head"><div><h3>Trường dữ liệu</h3><p>Thêm, sửa, nhân bản và sắp xếp trường ngay trong CMS.</p></div><button type="button" class="btn glass" id="add-field">＋ Thêm trường</button></div><div id="fields-builder"></div><h3>Xác nhận & bảo vệ người chưa thành niên</h3><div class="form-grid two"><label>Tiêu đề xác nhận<input name="confirmation_title" value="${esc(data.settings?.confirmation_title||'Đã nhận hồ sơ')}"></label><label class="choice"><input type="checkbox" name="confirmation_email" ${data.settings?.confirmation_email!==false?'checked':''}> Gửi email xác nhận</label><label class="full">Nội dung xác nhận<textarea name="confirmation_message">${esc(data.settings?.confirmation_message||'Xanh Sky First đã ghi nhận thông tin của bạn.')}</textarea></label><label class="full">Thông báo khi đóng<textarea name="closed_message">${esc(data.settings?.closed_message||'Biểu mẫu hiện không nhận thêm hồ sơ.')}</textarea></label><label class="choice"><input type="checkbox" name="require_guardian_consent" ${data.settings?.require_guardian_consent?'checked':''}> Yêu cầu xác nhận cho người chưa thành niên</label><label class="full">Ghi chú người giám hộ<textarea name="guardian_note">${esc(data.settings?.guardian_note||'')}</textarea></label></div><div class="sticky-actions"><button type="button" class="btn glass modal-close2">Hủy</button><button class="btn primary">${form?'Lưu biểu mẫu':'Tạo biểu mẫu'}</button></div></form>`,true);
  $('.modal-close',m).onclick=$('.modal-close2',m).onclick=closeModal;
  const editor=$('#form-editor',m),builder=$('#fields-builder',m);
  const render=()=>{builder.innerHTML=fields.map(fieldEditorRow).join('')||'<div class="empty small">Chưa có trường tùy chỉnh.</div>';$$('.builder-row',builder).forEach(row=>{const i=Number(row.dataset.i),sync=()=>{const r=fields[i];r.type=$('.field-type',row).value;r.label=$('.field-label',row).value;r.required=$('.field-required',row).checked;r.options=$('.field-options',row).value.split('|').map(x=>x.trim()).filter(Boolean);r.id=r.id||`field-${i+1}`;render()};$('.field-type',row).onchange=sync;$('.field-label',row).oninput=e=>{fields[i].label=e.target.value;state.dirty=true};$('.field-required',row).onchange=e=>{fields[i].required=e.target.checked;state.dirty=true};$('.field-options',row).oninput=e=>{fields[i].options=e.target.value.split('|').map(x=>x.trim()).filter(Boolean);state.dirty=true};$('.field-up',row).onclick=()=>{if(i>0){[fields[i-1],fields[i]]=[fields[i],fields[i-1]];render();state.dirty=true}};$('.field-down',row).onclick=()=>{if(i<fields.length-1){[fields[i+1],fields[i]]=[fields[i],fields[i+1]];render();state.dirty=true}};$('.field-dup',row).onclick=()=>{fields.splice(i+1,0,{...structuredClone(fields[i]),id:`field-${Date.now()}`});render();state.dirty=true};$('.field-del',row).onclick=()=>{fields.splice(i,1);render();state.dirty=true}})};render();
  $('#add-field',m).onclick=()=>{fields.push({id:`field-${Date.now()}`,type:'text',label:'Trường mới',required:false,options:[]});render();state.dirty=true};
  $('#choose-form-cover',m).onclick=()=>openMediaPicker({currentId:editor.cover_media_id.value,onSelect:item=>{editor.cover_media_id.value=item.id;$('#form-cover-preview',m).innerHTML=`<img src="${item.url}" alt="${esc(item.alt_text||item.filename)}">`;state.dirty=true}});
  $('#remove-form-cover',m).onclick=()=>{editor.cover_media_id.value='';$('#form-cover-preview',m).innerHTML='<div class="empty small">Chưa chọn ảnh</div>';state.dirty=true};
  editor.oninput=()=>state.dirty=true;
  editor.onsubmit=async e=>{e.preventDefault();const f=new FormData(editor),body={name:f.get('name'),slug:f.get('slug'),kind:f.get('kind'),status:f.get('status'),description:f.get('description'),opens_at:f.get('opens_at')?new Date(f.get('opens_at')).toISOString():null,closes_at:f.get('closes_at')?new Date(f.get('closes_at')).toISOString():null,capacity:f.get('capacity')?Number(f.get('capacity')):null,cover_media_id:f.get('cover_media_id')?Number(f.get('cover_media_id')):null,fields,settings:{confirmation_title:f.get('confirmation_title'),confirmation_message:f.get('confirmation_message'),confirmation_email:f.has('confirmation_email'),closed_message:f.get('closed_message'),require_guardian_consent:f.has('require_guardian_consent'),guardian_note:f.get('guardian_note')}};try{if(form)await api(`/api/admin/form/${form.id}`,{method:'PUT',body});else await api('/api/admin/forms',{method:'POST',body});state.dirty=false;closeModal();toast('Đã lưu Form Builder');admin('forms')}catch(x){toast(x.message,'error')}};
}

function blockRow(b,i){
  const textTypes=['paragraph','heading','quote','callout','cta'];
  return `<div class="content-block" data-i="${i}"><div class="content-block-head"><b>${esc(b.type)}</b><div><button type="button" class="icon-btn block-up">↑</button><button type="button" class="icon-btn block-down">↓</button><button type="button" class="icon-btn block-dup">⧉</button><button type="button" class="icon-btn block-del">×</button></div></div>${textTypes.includes(b.type)?`<textarea class="block-text" placeholder="Nội dung">${esc(b.text||'')}</textarea>`:''}${b.type==='callout'?`<input class="block-title" placeholder="Tiêu đề callout" value="${esc(b.title||'')}">`:''}${b.type==='cta'?`<div class="form-grid two"><input class="block-label" placeholder="Nhãn nút" value="${esc(b.label||'')}"/><input class="block-href" placeholder="/tham-gia" value="${esc(b.href||'')}"/></div>`:''}${b.type==='image'?`${b.media_id?`<img class="block-image-preview" src="/api/media/${b.media_id}" alt="">`:'<div class="empty small">Chưa chọn ảnh</div>'}<button type="button" class="btn glass block-pick-image">Chọn ảnh</button><input class="block-alt" placeholder="Alt text" value="${esc(b.alt||'')}"><input class="block-caption" placeholder="Caption" value="${esc(b.caption||'')}">`:''}${b.type==='gallery'?`<div class="gallery-editor">${(b.media_ids||[]).map(id=>`<img src="/api/media/${id}" alt="">`).join('')}</div><button type="button" class="btn glass block-add-gallery">＋ Thêm ảnh</button>`:''}${b.type==='spacer'?`<input class="block-height" type="number" min="16" max="160" value="${Number(b.height||48)}">`:''}${b.type==='table'?`<textarea class="block-table" placeholder="Mỗi dòng một hàng; phân cột bằng |">${esc((b.rows||[]).map(r=>r.join(' | ')).join('\n'))}</textarea>`:''}${b.type==='stats'?`<textarea class="block-stats" placeholder="Giá trị | Nhãn, mỗi dòng một mục">${esc((b.items||[]).map(x=>`${x.value} | ${x.label}`).join('\n'))}</textarea>`:''}</div>`;
}
function createBlock(type){if(type==='image')return {type,media_id:null,alt:'',caption:''};if(type==='gallery')return {type,media_ids:[]};if(type==='spacer')return {type,height:48};if(type==='table')return {type,rows:[]};if(type==='stats')return {type,items:[]};if(type==='cta')return {type,text:'',label:'Cùng hành động',href:'/tham-gia'};if(type==='callout')return {type,title:'',text:''};return {type,text:''}}
function wireBlocks(builder,body){
  const render=()=>{builder.innerHTML=body.map(blockRow).join('')||'<div class="empty small">Chưa có block nội dung.</div>';$$('.content-block',builder).forEach(row=>{const i=Number(row.dataset.i),b=body[i];const dirty=()=>state.dirty=true;$('.block-text',row)?.addEventListener('input',e=>{b.text=e.target.value;dirty()});$('.block-title',row)?.addEventListener('input',e=>{b.title=e.target.value;dirty()});$('.block-label',row)?.addEventListener('input',e=>{b.label=e.target.value;dirty()});$('.block-href',row)?.addEventListener('input',e=>{b.href=e.target.value;dirty()});$('.block-alt',row)?.addEventListener('input',e=>{b.alt=e.target.value;dirty()});$('.block-caption',row)?.addEventListener('input',e=>{b.caption=e.target.value;dirty()});$('.block-height',row)?.addEventListener('input',e=>{b.height=Number(e.target.value);dirty()});$('.block-table',row)?.addEventListener('input',e=>{b.rows=e.target.value.split('\n').filter(Boolean).map(r=>r.split('|').map(c=>c.trim()));dirty()});$('.block-stats',row)?.addEventListener('input',e=>{b.items=e.target.value.split('\n').filter(Boolean).map(r=>{const [value,...lab]=r.split('|');return {value:(value||'').trim(),label:lab.join('|').trim()}});dirty()});$('.block-up',row).onclick=()=>{if(i>0){[body[i-1],body[i]]=[body[i],body[i-1]];render();dirty()}};$('.block-down',row).onclick=()=>{if(i<body.length-1){[body[i+1],body[i]]=[body[i],body[i+1]];render();dirty()}};$('.block-dup',row).onclick=()=>{body.splice(i+1,0,structuredClone(b));render();dirty()};$('.block-del',row).onclick=()=>{body.splice(i,1);render();dirty()};$('.block-pick-image',row)?.addEventListener('click',()=>openMediaPicker({currentId:b.media_id,onSelect:item=>{b.media_id=item.id;b.alt=b.alt||item.alt_text||item.filename;render();dirty()}}));$('.block-add-gallery',row)?.addEventListener('click',()=>openMediaPicker({onSelect:item=>{b.media_ids=b.media_ids||[];b.media_ids.push(item.id);render();dirty()}}))})};render();return render;
}
async function contentAdmin(tab){
  const type=typeMap[tab],x=(await api(`/api/admin/content?type=${type}`)).items;
  return adminHead(labels[tab],`Viết, lưu nháp, xuất bản, hẹn giờ và quản lý ${labels[tab].toLowerCase()} bằng block editor.`,`<button class="btn primary" data-action="new-content" data-type="${type}">＋ Viết mới</button>`)+table(x.map(i=>[`<b>${esc(i.title)}</b><br><small>/${esc(i.slug)}</small>`,statusBadge(i.status),esc(i.category||'—'),i.metadata?.scheduled_at?`Hẹn ${date(i.metadata.scheduled_at)}`:date(i.updated_at),`<button class="link-btn edit-content" data-id="${i.id}" data-type="${type}">Sửa</button> · <a data-nav href="/${publicType[type].base}/${esc(i.slug)}">Xem ↗</a>`]),['Tiêu đề','Trạng thái','Chuyên mục','Cập nhật','Thao tác']);
}
async function contentEditor(type,item=null){
  let body=structuredClone(item?.body||[]),cover=item?.cover_media_id?{id:item.cover_media_id,url:item.cover_url}:null,meta=structuredClone(item?.metadata||{});
  const m=makeModal(`<div class="modal-head"><div><span class="eyebrow">CONTENT EDITOR</span><h2>${item?'Chỉnh sửa':'Viết mới'} · ${esc(publicType[type]?.title||type)}</h2></div><button class="icon-btn modal-close">×</button></div><form id="content-editor"><div class="form-grid two"><label class="full">Tiêu đề<input name="title" value="${esc(item?.title||'')}" required></label><label>Slug<input name="slug" value="${esc(item?.slug||'')}"></label><label>Chuyên mục<input name="category" value="${esc(item?.category||'')}"></label><label class="full">Mô tả ngắn<textarea name="excerpt">${esc(item?.excerpt||'')}</textarea></label><label>Trạng thái<select name="status">${['draft','published','open','closed','completed','reviewing','archived'].map(s=>`<option value="${s}" ${item?.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Hẹn xuất bản<input name="scheduled_at" type="datetime-local" value="${localDateTime(meta.scheduled_at)}"></label><label>Địa điểm<input name="location" value="${esc(item?.location||'')}"></label><label>Sức chứa<input name="capacity" type="number" value="${item?.capacity||''}"></label><label>Bắt đầu<input name="starts_at" type="datetime-local" value="${localDateTime(item?.starts_at)}"></label><label>Kết thúc<input name="ends_at" type="datetime-local" value="${localDateTime(item?.ends_at)}"></label></div><div class="cover-editor"><h3>Ảnh đại diện</h3><div id="content-cover-preview">${cover?`<img src="${cover.url}" alt="">`:'<div class="empty small">Chưa chọn ảnh</div>'}</div><input type="hidden" name="cover_media_id" value="${cover?.id||''}"><button type="button" class="btn glass" id="choose-content-cover">Chọn / tải ảnh</button><button type="button" class="btn danger" id="remove-content-cover">Gỡ ảnh</button></div><div class="builder-head"><div><h3>Nội dung</h3><p>Block editor trực quan; ảnh lấy từ R2 Media Library.</p></div><div class="block-add-menu">${['paragraph','heading','image','gallery','quote','callout','cta','table','stats','spacer'].map(t=>`<button type="button" class="btn glass add-block" data-type="${t}">＋ ${t}</button>`).join('')}</div></div><div id="content-blocks"></div><h3>SEO</h3><div class="form-grid two"><label>SEO title<input name="seo_title" value="${esc(meta.seo?.title||'')}"></label><label class="full">SEO description<textarea name="seo_description">${esc(meta.seo?.description||'')}</textarea></label></div><div class="sticky-actions"><button type="button" class="btn glass" id="preview-content">Preview</button><button type="button" class="btn glass modal-close2">Hủy</button><button class="btn primary">${item?'Lưu thay đổi':'Tạo nội dung'}</button></div></form>`,true);
  $('.modal-close',m).onclick=$('.modal-close2',m).onclick=closeModal;const form=$('#content-editor',m),builder=$('#content-blocks',m);wireBlocks(builder,body);
  $$('.add-block',m).forEach(btn=>btn.onclick=()=>{body.push(createBlock(btn.dataset.type));wireBlocks(builder,body);state.dirty=true});
  $('#choose-content-cover',m).onclick=()=>openMediaPicker({currentId:form.cover_media_id.value,onSelect:x=>{form.cover_media_id.value=x.id;$('#content-cover-preview',m).innerHTML=`<img src="${x.url}" alt="${esc(x.alt_text||x.filename)}">`;state.dirty=true}});
  $('#remove-content-cover',m).onclick=()=>{form.cover_media_id.value='';$('#content-cover-preview',m).innerHTML='<div class="empty small">Chưa chọn ảnh</div>';state.dirty=true};
  $('#preview-content',m).onclick=()=>{const f=new FormData(form);const p=makeModal(`<div class="modal-head"><h2>${esc(f.get('title')||'Preview')}</h2><button class="icon-btn modal-close">×</button></div><article class="prose preview-prose">${renderRichBlocks(body)}</article>`,true);$('.modal-close',p).onclick=closeModal};
  form.oninput=()=>state.dirty=true;
  form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);meta.seo={title:f.get('seo_title'),description:f.get('seo_description')};const bodyData={type,title:f.get('title'),slug:f.get('slug'),category:f.get('category'),excerpt:f.get('excerpt'),status:f.get('status'),scheduled_at:f.get('scheduled_at')?new Date(f.get('scheduled_at')).toISOString():null,location:f.get('location'),capacity:f.get('capacity')?Number(f.get('capacity')):null,starts_at:f.get('starts_at')?new Date(f.get('starts_at')).toISOString():null,ends_at:f.get('ends_at')?new Date(f.get('ends_at')).toISOString():null,cover_media_id:f.get('cover_media_id')?Number(f.get('cover_media_id')):null,body,metadata:meta};try{if(item)await api(`/api/admin/content-item/${item.id}`,{method:'PUT',body:bodyData});else await api('/api/admin/content',{method:'POST',body:bodyData});state.dirty=false;closeModal();toast('Đã lưu nội dung');admin(Object.keys(typeMap).find(k=>typeMap[k]===type)||'articles')}catch(x){toast(x.message,'error')}};
}

async function pagesAdmin(){
  const x=(await api('/api/admin/pages')).items;
  return adminHead('Trang & Page Builder','Quản lý trang tĩnh, trang pháp lý, SEO và revision. Homepage vẫn giữ các block chuyên biệt.',`<button class="btn primary" id="new-page">＋ Tạo trang</button>`)+table(x.map(p=>[`<b>${esc(p.title)}</b><br><small>/${esc(p.slug==='home'?'':p.slug)}</small>`,statusBadge(p.status),(p.blocks||[]).length,date(p.updated_at),`<button class="link-btn edit-page" data-id="${p.id}">Sửa</button>`]),['Trang','Trạng thái','Blocks','Cập nhật','Thao tác']);
}
function createHomeBlock(type){const base={id:`${type}-${Date.now()}`,type,visible:true};if(type==='hero')return {...base,eyebrow:'XANH SKY FIRST · MÔI TRƯỜNG & PHÁT TRIỂN BỀN VỮNG',title:'HÀNH ĐỘNG HÔM NAY. XANH NGÀY MAI.',body:'Xanh Sky First kết nối người trẻ, cộng đồng, tri thức và nguồn lực để biến sự quan tâm dành cho môi trường thành hành động có thể bắt đầu từ thực tế.',primary_label:'Khám phá Xanh',primary_href:'/gioi-thieu',secondary_label:'Cùng hành động',secondary_href:'/tham-gia',side_title:'Lan tỏa lối sống xanh',side_body:'Từ hiểu vấn đề đến cùng cộng đồng hành động.'};if(type==='rich')return {...base,kicker:'VỀ XANH SKY FIRST',title:'Một không gian để sự quan tâm trở thành hành động',body:'Xanh Sky First ưu tiên chất lượng của từng hoạt động, tính minh bạch và khả năng tạo ra giá trị bền vững.'};if(type==='cards'||type==='feature_grid')return {...base,kicker:'LĨNH VỰC HÀNH ĐỘNG',title:'Năm hướng để bắt đầu',items:[{title:'Môi trường & không gian sống',body:'Tìm hiểu những vấn đề gần gũi với nơi chúng ta sống.'},{title:'Giáo dục môi trường',body:'Tiếp cận kiến thức rõ ràng và dễ áp dụng.'}]};if(type==='dynamic')return {...base,source:'project',kicker:'CHƯƠNG TRÌNH & DỰ ÁN',title:'Nội dung được công bố'};if(type==='impact')return {...base,kicker:'DẤU ẤN XANH',title:'Mỗi con số đại diện cho một hành động đã thực sự diễn ra.'};if(type==='newsletter')return {...base,kicker:'NEWSLETTER',title:'Một chút Xanh trong hộp thư của bạn.',body:'Chỉ nhận những nội dung bạn đã chủ động chọn. Bạn có thể hủy đăng ký khi cần.'};if(type==='cta')return {...base,title:'Không cần bắt đầu bằng điều lớn.',body:'Chọn một cách phù hợp để cùng hành động.',label:'Cùng hành động',href:'/tham-gia'};return {...base,title:'Nội dung mới',body:''}}
function homeBlockRow(b,i){const fields=['eyebrow','kicker','title','body','primary_label','primary_href','secondary_label','secondary_href','side_title','side_body','label','href'];const common=fields.filter(k=>k in b||(['hero'].includes(b.type)&&['eyebrow','title','body','primary_label','primary_href','secondary_label','secondary_href','side_title','side_body'].includes(k))||(['rich','cards','feature_grid','dynamic','impact','newsletter','cta'].includes(b.type)&&['kicker','title','body','label','href'].includes(k)));const fieldHtml=common.map(k=>{const long=['body','side_body'].includes(k);return `<label class="${long?'full':''}">${({eyebrow:'Hero kicker',kicker:'Nhãn khu vực',title:'Tiêu đề',body:'Nội dung / mô tả',primary_label:'Nút chính',primary_href:'Liên kết nút chính',secondary_label:'Nút phụ',secondary_href:'Liên kết nút phụ',side_title:'Tiêu đề thẻ bên phải',side_body:'Mô tả thẻ bên phải',label:'Nhãn nút',href:'Đường dẫn nút'})[k]||k}${long?`<textarea data-home-field="${k}">${esc(b[k]||'')}</textarea>`:`<input data-home-field="${k}" value="${esc(b[k]||'')}">`}</label>`}).join('');return `<article class="home-block-editor" data-i="${i}"><header><div><span class="eyebrow">BLOCK ${String(i+1).padStart(2,'0')}</span><b>${esc(b.type)}</b></div><div><button type="button" class="icon-btn home-up">↑</button><button type="button" class="icon-btn home-down">↓</button><button type="button" class="icon-btn home-dup">⧉</button><button type="button" class="icon-btn home-del">×</button></div></header><label class="choice"><input data-home-field="visible" type="checkbox" ${b.visible!==false?'checked':''}> Hiển thị khu vực</label>${b.type==='hero'?`<div class="home-image-picker">${b.media_id?`<img src="/api/media/${Number(b.media_id)}" alt="Ảnh hero hiện tại">`:'<div class="empty small">Đang dùng ảnh phong cảnh mặc định; có thể thay bằng ảnh thật trong Media Library.</div>'}<input type="hidden" data-home-field="media_id" value="${b.media_id||''}"><button type="button" class="btn glass home-pick-image">Chọn ảnh thiên nhiên từ Media Library</button><button type="button" class="btn danger home-remove-image">Dùng ảnh mặc định</button></div>`:''}<div class="form-grid two">${fieldHtml}</div>${['cards','feature_grid'].includes(b.type)?`<label class="full">Các thẻ (mỗi dòng: Tiêu đề | Mô tả)<textarea data-home-items rows="5">${esc((b.items||[]).map(x=>`${typeof x==='string'?x:x.title||''} | ${typeof x==='string'?'':x.body||''}`).join('\n'))}</textarea></label>`:''}${b.type==='dynamic'?`<label>Nguồn nội dung<select data-home-field="source">${[['project','Dự án'],['activity','Hoạt động'],['opportunity','Cơ hội'],['resource','Tài nguyên'],['article','Tin tức'],['initiative','Sáng kiến']].map(([v,l])=>`<option value="${v}" ${b.source===v?'selected':''}>${l}</option>`).join('')}</select></label>`:''}</article>`}
function wireHomeBlocks(builder,body){const render=()=>{builder.innerHTML=body.map(homeBlockRow).join('')||'<div class="empty">Trang chủ chưa có block nào. Thêm block phía trên.</div>';$$('.home-block-editor',builder).forEach(row=>{const i=Number(row.dataset.i),b=body[i],dirty=()=>state.dirty=true;$$('[data-home-field]',row).forEach(el=>el.addEventListener(el.type==='checkbox'||el.tagName==='SELECT'?'change':'input',()=>{const k=el.dataset.homeField;if(k==='media_id')b.media_id=el.value?Number(el.value):null;else b[k]=el.type==='checkbox'?el.checked:el.value;dirty()}));$('[data-home-items]',row)?.addEventListener('input',e=>{b.items=e.target.value.split('\n').filter(Boolean).map(line=>{const [title,...rest]=line.split('|');return {title:title.trim(),body:rest.join('|').trim()}});dirty()});$('.home-up',row).onclick=()=>{if(i>0){[body[i-1],body[i]]=[body[i],body[i-1]];render();dirty()}};$('.home-down',row).onclick=()=>{if(i<body.length-1){[body[i+1],body[i]]=[body[i],body[i+1]];render();dirty()}};$('.home-dup',row).onclick=()=>{body.splice(i+1,0,structuredClone(b));render();dirty()};$('.home-del',row).onclick=()=>{if(confirm('Xóa block khỏi trang chủ?')){body.splice(i,1);render();dirty()}};$('.home-pick-image',row)?.addEventListener('click',()=>openMediaPicker({currentId:b.media_id,onSelect:item=>{b.media_id=item.id;render();dirty()}}));$('.home-remove-image',row)?.addEventListener('click',()=>{b.media_id=null;render();dirty()})})};render();return render}
async function pageEditor(page=null){
  let blocks=structuredClone(page?.blocks||[]);const isHome=page?.slug==='home';
  const choices=isHome?['hero','rich','cards','feature_grid','dynamic','impact','newsletter','cta']:['paragraph','heading','image','quote','callout','cta','table','spacer'];
  const m=makeModal(`<div class="modal-head"><div><span class="eyebrow">PAGE BUILDER</span><h2>${page?'Chỉnh sửa trang':'Tạo trang'}${isHome?' · Homepage Builder':''}</h2></div><button class="icon-btn modal-close">×</button></div><form id="page-editor"><div class="form-grid two"><label>Tiêu đề<input name="title" value="${esc(page?.title||'')}" required></label><label>Slug<input name="slug" value="${esc(page?.slug||'')}" ${page?'readonly':''}></label><label>Trạng thái<select name="status"><option value="draft" ${page?.status==='draft'?'selected':''}>Bản nháp</option><option value="published" ${page?.status==='published'?'selected':''}>Đã xuất bản</option><option value="archived" ${page?.status==='archived'?'selected':''}>Lưu trữ</option></select></label></div><div class="builder-head"><div><h3>${isHome?'Các khu vực trang chủ':'Nội dung trang'}</h3><p>${isHome?'Thêm, sửa, đổi thứ tự, nhân bản hoặc ẩn từng block. Bốn ô số lấy giá trị cuối từ Impact đã xác minh.':'Mỗi block có thể chỉnh sửa riêng; nội dung được lưu trong CMS.'}</p><button type="button" class="btn glass" id="page-preview">Xem trước bản chưa xuất bản</button></div><div class="block-add-menu">${choices.map(t=>`<button type="button" class="btn glass add-page-block" data-type="${t}">＋ ${t}</button>`).join('')}</div></div><div id="page-preview-inline" class="page-preview-inline" hidden></div><div id="page-blocks"></div><h3>SEO</h3><div class="form-grid two"><label>SEO title<input name="seo_title" value="${esc(page?.seo?.title||'')}"></label><label class="full">SEO description<textarea name="seo_description">${esc(page?.seo?.description||'')}</textarea></label></div><div class="sticky-actions"><button type="button" class="btn glass modal-close2">Hủy</button><button class="btn primary">Lưu ${isHome?'trang chủ':'trang'}</button></div></form>`,true);
  $('.modal-close',m).onclick=$('.modal-close2',m).onclick=closeModal;const form=$('#page-editor',m),builder=$('#page-blocks',m);const redraw=isHome?wireHomeBlocks:wireBlocks;redraw(builder,blocks);$$('.add-page-block',m).forEach(btn=>btn.onclick=()=>{blocks.push(isHome?createHomeBlock(btn.dataset.type):createBlock(btn.dataset.type));redraw(builder,blocks);state.dirty=true});form.oninput=()=>state.dirty=true;$('#page-preview',m).onclick=async()=>{const panel=$('#page-preview-inline',m);try{let body='';if(isHome){let impact={};try{impact=(await api('/api/public/impact')).impact}catch{};for(const b of blocks)body+=await renderHomeBlock(b,impact)}else body=`<section class="page-hero"><span class="eyebrow">XANH SKY FIRST</span><h1>${esc(form.elements.title.value||'Bản xem trước')}</h1></section><article class="prose">${renderRichBlocks(blocks)}</article>`;panel.innerHTML=`<div class="preview-label">BẢN XEM TRƯỚC · CHƯA XUẤT BẢN</div><div class="preview-site">${header()}<main>${body}</main>${footer()}</div>`;panel.hidden=false;panel.scrollIntoView({behavior:'smooth',block:'nearest'});panel.onclick=e=>{if(e.target.closest('a')){e.preventDefault();e.stopPropagation()}}}catch(x){toast('Không tạo được bản xem trước: '+x.message,'error')}};
  form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),data={title:f.get('title'),slug:f.get('slug'),status:f.get('status'),blocks,seo:{title:f.get('seo_title'),description:f.get('seo_description')}};try{if(page)await api(`/api/admin/page/${page.id}`,{method:'PUT',body:data});else await api('/api/admin/pages',{method:'POST',body:data});state.dirty=false;state.site=null;closeModal();toast('Đã lưu trang');admin('pages')}catch(x){toast(x.message,'error')}};
}

